enum LegalDocumentType { privacy, terms, purchase }

class LegalDocument {
  const LegalDocument({
    required this.type,
    required this.title,
    required this.localizedOverview,
    required this.englishMaster,
  });

  final LegalDocumentType type;
  final String title;
  final String localizedOverview;
  final String englishMaster;
}

